const state = $node["Refresh Thread State"].json;
const candidatesNode = $node["Normalize Thread Candidates"].json;

let inferred = {};
try {
  const updaterOutput = $node["Parser Updater Output"].json;
  const patch = updaterOutput?.candidate_patch || {};
  const create = updaterOutput?.candidate_create || {};
  // When a candidate is being created this turn, tipo_vehiculo lives in candidate_create
  inferred = { ...create, ...patch };
} catch(e) {
  inferred = {};
}

const candidates = candidatesNode.candidates || [];
const focusId = state.current_focus_candidate_id;

let focusCandidate = null;

if (focusId != null) {
  focusCandidate = candidates.find(c => c.id === focusId) || null;
}

// fallback: if no focus id, try candidate with current_focus
if (!focusCandidate) {
  focusCandidate = candidates.find(c => c.status === "current_focus") || null;
}

if (!focusCandidate) {
  return [
    {
      json: {
        effective_state: null,
        ready_for_price: false,
        missing_fields: ["candidate"]
      }
    }
  ];
}

const normalize = (value) =>
  (value || "")
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase();

// infer zone_group from zone_detail when possible
const inferZoneGroupFromDetail = (zoneDetail) => {
  const z = normalize(zoneDetail);

  if (!z) return null;

  const cabaDetails = [
    "agronomia", "almagro", "balvanera", "belgrano", "caballito",
    "chacarita", "coghlan", "colegiales", "flores", "floresta",
    "la boca", "liniers", "mataderos", "monserrat", "monte castro",
    "nunez", "palermo", "parque avellaneda", "parque chacabuco",
    "parque chas", "parque patricios", "paternal", "pompeya",
    "puerto madero", "recoleta", "retiro", "saavedra", "san cristobal",
    "san nicolas", "san telmo", "velez sarsfield", "versalles",
    "villa crespo", "villa del parque", "villa devoto", "villa general mitre",
    "villa lugano", "villa luro", "villa ortuzar", "villa pueyrredon",
    "villa real", "villa santa rita", "villa soldati", "villa urquiza"
  ];
  if (cabaDetails.includes(z)) return "CABA";

  const norteDetails = [
    "acassuso", "beccar", "boulogne", "don torcuato", "el talar",
    "escobar", "garin", "general pacheco", "ingeniero maschwitz",
    "martinez", "munro", "olivos", "pacheco", "pilar", "san fernando",
    "san isidro", "tigre", "torcuato", "victoria", "vicente lopez",
    "malvinas argentinas", "jose c. paz", "zarate", "campana",
    "san miguel"
  ];
  if (norteDetails.includes(z)) return "Norte";

  const oesteDetails = [
    "castelar", "haedo", "ituzaingo", "moreno", "moron", "padua",
    "paso del rey", "ramos mejia", "san antonio de padua", "merlo",
    "hurlingham", "san martin", "3 de febrero", "general rodriguez",
    "marcos paz", "lujan",
    "lomas del mirador", "la matanza oeste", "canuelas",
    "exaltacion de la cruz", "general las heras"
  ];
  if (oesteDetails.includes(z)) return "Oeste";

  const surDetails = [
    "adrogue", "avellaneda", "banfield", "berazategui", "burzaco",
    "calzada", "ezeiza", "glew", "lanus", "lomas de zamora",
    "longchamps", "monte grande", "quilmes", "san francisco solano",
    "temperley", "florencio varela", "la plata", "almirante brown",
    "presidente peron"
  ];
  if (surDetails.includes(z)) return "Sur";

  return null;
};

// Use candidate data with fallback to planner inferred data
const effectiveTipoVehiculo = focusCandidate.tipo_vehiculo || inferred.tipo_vehiculo || null;
let effectiveZoneGroup = focusCandidate.zone_group || inferred.zone_group || null;
const effectiveZoneDetail = focusCandidate.zone_detail || inferred.zone_detail || null;

// if zone_group is missing but zone_detail is known, try to infer it
if (!effectiveZoneGroup && effectiveZoneDetail) {
  effectiveZoneGroup = inferZoneGroupFromDetail(effectiveZoneDetail);
}

// ── M17.4 Fix 4: scan recent inbound messages for zone if still missing ──
if (!effectiveZoneDetail) {
  try {
    const recentMsgs = $node["Build Conversation Context"].json.recent_user_messages || [];
    // Scan newest-first for a message whose full text is a known locality
    for (let i = recentMsgs.length - 1; i >= 0; i--) {
      const msgNorm = normalize(recentMsgs[i]);
      const zg = inferZoneGroupFromDetail(msgNorm);
      if (zg) {
        effectiveZoneDetail = recentMsgs[i].trim();
        effectiveZoneGroup = zg;
        break;
      }
    }
  } catch(e) { /* silent fallback */ }
}

const missing = [];
if (!effectiveTipoVehiculo) missing.push("tipo_vehiculo");

// only ask for location if zone_detail itself is missing.
if (!effectiveZoneDetail) {
  missing.push("zone_detail");
}

return [
  {
    json: {
      effective_state: {
        tipo_vehiculo: effectiveTipoVehiculo,
        zone_group: effectiveZoneGroup,
        zone_detail: effectiveZoneDetail,
        marca: focusCandidate.marca ?? null,
        modelo: focusCandidate.modelo ?? null,
        anio: focusCandidate.anio ?? null,
        candidate_id: focusCandidate.id
      },
      ready_for_price: missing.length === 0,
      missing_fields: missing
    }
  }
];

const current_execution_message = $node["Webhook"].json["body"]["wa_message_id"];
