const results = $input.first().json.results;
if (!results || results.length === 0) {
  return [{ json: { zone_group: null, zone_detail: null, resolved: false, tipo_vehiculo: $node["Price Inputs"].json["tipo_vehiculo"] } }];
}
const components = results[0].address_components;
const partido = components.find(c => c.types.includes("administrative_area_level_2"))?.long_name || null;
const localidad = components.find(c => c.types.includes("locality") || c.types.includes("sublocality"))?.long_name || null;
const lat = results[0].geometry?.location?.lat || null;
const lng = results[0].geometry?.location?.lng || null;

const nortePartidos = ["Tigre", "San Fernando", "San Isidro", "Vicente López", "Pilar", "Escobar", "San Miguel", "Malvinas Argentinas", "José C. Paz", "Zárate", "Campana"];
const oestePartidos = ["Morón", "Ituzaingó", "Hurlingham", "Merlo", "Moreno", "Tres de Febrero", "General Rodríguez", "Marcos Paz", "Luján", "Cañuelas", "General Las Heras", "Exaltación de la Cruz", "La Matanza", "San Martín", "3 de Febrero"];
const surPartidos = ["Lanús", "Avellaneda", "Lomas de Zamora", "Quilmes", "Berazategui", "Florencio Varela", "Ezeiza", "La Plata", "Almirante Brown", "Esteban Echeverría", "Presidente Perón", "Berisso", "Ensenada", "Coronel Brandsen", "San Vicente"];
const cabaPartidos = ["Ciudad Autónoma de Buenos Aires", "Buenos Aires"];

const normalize = (s) => (s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim();

let zone_group = null;
const np = normalize(partido);

// Match por partido
if (nortePartidos.some(p => np.includes(normalize(p)) || normalize(p).includes(np))) zone_group = "Norte";
else if (oestePartidos.some(p => np.includes(normalize(p)) || normalize(p).includes(np))) zone_group = "Oeste";
else if (surPartidos.some(p => np.includes(normalize(p)) || normalize(p).includes(np))) zone_group = "Sur";
else if (cabaPartidos.some(p => np.includes(normalize(p)) || normalize(p).includes(np))) zone_group = "CABA";

// Fallback: CABA por short_name o formatted_address
if (!zone_group) {
  const fullAddress = results[0].formatted_address || "";
  if (cabaPartidos.some(p => fullAddress.includes(p)) || components.some(c => c.short_name === "CABA")) {
    zone_group = "CABA";
  }
}

// Fallback: buscar por localidad
if (!zone_group && localidad) {
  const nl = normalize(localidad);
  if (nortePartidos.some(p => normalize(p).includes(nl) || nl.includes(normalize(p)))) zone_group = "Norte";
  else if (oestePartidos.some(p => normalize(p).includes(nl) || nl.includes(normalize(p)))) zone_group = "Oeste";
  else if (surPartidos.some(p => normalize(p).includes(nl) || nl.includes(normalize(p)))) zone_group = "Sur";
}

// Fallback final: por coordenadas
if (!zone_group && lat && lng) {
  if (lat >= -34.705 && lat <= -34.527 && lng >= -58.531 && lng <= -58.334) {
    zone_group = "CABA";
  } else if (lat > -34.527 && lat <= -34.0 && lng >= -58.7 && lng <= -58.2) {
    zone_group = "Norte";
  } else if (lat >= -34.9 && lat <= -34.4 && lng < -58.531 && lng >= -59.2) {
    zone_group = "Oeste";
  } else if (lat < -34.705 && lat >= -35.5 && lng >= -58.6 && lng <= -57.8) {
    zone_group = "Sur";
  }
}

const partidoNorm = partido ? partido.replace(/\s*Partido\s*/i, "").trim() : null;
const zone_detail = localidad || partidoNorm || $node["Price Inputs"].json["zone_detail"];

return [{ 
  json: { 
    zone_group, 
    zone_detail,
    partido,
    resolved: zone_group !== null,
    tipo_vehiculo: $node["Price Inputs"].json["tipo_vehiculo"]
  } 
}];

