// M15.1 — Booking Ready Check (M17.5: simplified — requires prior quote + scheduling intent)
// Address/seller/buyer data is now collected via WhatsApp Flow form, not in conversation.

const updater = $node["Parser Updater Output"].json;
const bookingSignals = updater.booking_signals || {};
const leadPatch      = updater.lead_patch || {};
const revPatch       = updater.lead_revision_patch || {};
const statePatch     = updater.state_patch || {};
const threadState    = $node["Refresh Thread State"].json;

// If Updater already confirmed revision_ready, pass through immediately.
if (bookingSignals.revision_ready === true) {
  return [{ json: { ...updater, booking_ready: true, recovered_day_text: null, recovered_time_text: null } }];
}

const isScheduling = (statePatch.last_stage === 'SCHEDULING') ||
                     (threadState.last_stage  === 'SCHEDULING');

// Fetch recent messages — needed both for quote check and day/time recovery.
const messages = ($node["Get Thread Messages 2"].json || {}).messages || [];

// M17.5: only enter scheduling path if a quote ($ amount) was already sent.
const hasOutboundQuote = messages.some(m => m.direction === 'out' && m.text && m.text.includes('$'));

if (!isScheduling || !hasOutboundQuote) {
  return [{ json: { ...updater, booking_ready: false, recovered_day_text: null, recovered_time_text: null } }];
}

// Try to recover preferred day/time from recent outbound bot messages.
// Pattern: "tomo [day] a las [time]" (written by the bot in prior turns).
let recoveredDay  = null;
let recoveredTime = null;

const DAY_PATTERN  = /tomo\s+(ma\u00f1ana|hoy|pasado|el\s+)?(\w+)/i;
const TIME_PATTERN = /a las\s+(\d{1,2}(?:[:\s]\d{2})?(?:hs)?)/i;

for (let i = messages.length - 1; i >= 0; i--) {
  const msg = messages[i];
  if (msg.direction !== 'out' || !msg.text) continue;
  const dm = msg.text.match(DAY_PATTERN);
  const tm = msg.text.match(TIME_PATTERN);
  if (dm && !recoveredDay)  recoveredDay  = (dm[1] ? dm[1].trim() + ' ' : '') + dm[2].trim();
  if (tm && !recoveredTime) recoveredTime = tm[1].replace(/\s+/, ':').replace(/hs$/, '').trim();
  if (recoveredDay) break;
}

// Also check booking_signals for a stored day from a different message burst.
const dayFromSignals  = bookingSignals.preferred_day_text  || null;
const timeFromSignals = bookingSignals.preferred_time_text || null;

const finalDay  = dayFromSignals  || recoveredDay  || null;
const finalTime = timeFromSignals || recoveredTime || null;

const bookingReady = !!(finalDay);  // day is the last required field

return [{ json: {
  ...updater,
  booking_ready: bookingReady,
  recovered_day_text:  recoveredDay,
  recovered_time_text: recoveredTime,
  booking_signals: {
    ...bookingSignals,
    preferred_day_text:  finalDay,
    preferred_time_text: finalTime,
  }
}}];

// M15.1 — Revision Truthful Guard
// Prevents the bot from saying "solicitud registrada" when no revision was
// actually created (current_revision_id is still null in thread state).

const currentRevisionId = $node["Refresh Thread State"].json["current_revision_id"];
const finalReply = ($json["final_reply_text"] || "").trim();

const FALSE_PHRASES = [
  "solicitud quedó registrada",
  "solicitud registrada",
];

const isFalseConfirmation = !currentRevisionId &&
  FALSE_PHRASES.some(p => finalReply.includes(p));

if (isFalseConfirmation) {
  return [{
    json: {
      final_reply_text: "Tengo los datos, pero lo dejo marcado para que el equipo lo revise y lo cargue manualmente.",
      needs_human_triggered: true,
    }
  }];
}

return [{
  json: {
    ...($json),
    needs_human_triggered: false,
  }
}];

// M14.3 — Informational Followup Check
// When the Router sets needs_human=true, detect if the latest user message is
// an informational follow-up that AI Reply Planner can handle directly.
// If yes → route to Vehicle Normalizer (normal AI path, planner reads NEEDS_HUMAN ACTIVE CONTEXT).
// If no  → route to Mark Leads Needs Human (true handoff path).

let latestMsg = "";
try { latestMsg = $node["Build Conversation Context"].json.latest_user_message || ""; } catch(e) {}
try { if (!latestMsg) latestMsg = ($node["Webhook"].json.body && $node["Webhook"].json.body.text) || ""; } catch(e) {}
latestMsg = latestMsg.toLowerCase().trim();

// Categories of informational follow-up that should bypass handoff:
// 1. Payment methods
// 2. Discount / pricing policy
// 3. Service info (FAQ)
// 4. Exception follow-up questions
const INFORMATIONAL_PATTERNS = [
  // Payment methods
  /medios?\s+de\s+pago/,
  /c[oó]mo\s+(se\s+)?pag/,
  /formas?\s+de\s+pago/,
  /\befectivo\b/,
  /\btransferencia\b/,
  /mercado\s*pago/,
  /\btarjeta(s)?\b/,
  /aceptan\s+\w/,
  /pagan\s+(con|por)\b/,
  /se\s+paga\s+con\b/,
  // Discount / pricing
  /\bdescuentos?\b/,
  /\brebajas?\b/,
  /m[aá]s\s+barato/,
  /\bprecios?\b/,
  /hacer(me)?\s+precio/,
  /alguna?\s+rebaja/,
  // Service info / FAQ
  /cu[aá]nto\s+tard[a-z]/,
  /cu[aá]nto\s+tiempo/,
  /estar\s+presente/,
  /obligatorio\b/,
  /d[oó]nde\s+se\s+realiza/,
  /qu[eé]\s+incluye/,
  /qu[eé]\s+(abarca|hacen|revisan)/,
  /c[oó]mo\s+funciona/,
  /\bgarant[ií]a\b/,
  /\binforme\b/,
  /\btiempo\b.*\brevis/,
  /\btiene[ns]?\s+que\s+estar/,
  // Exception follow-up
  /excepci[oó]n/,
  /no\s+pueden\b/,
  /no\s+pod[eé]s\b/,
  /no\s+puedes\b/,
  /no\s+pod[eé]is\b/,
  /hacer\s+una\s+excepci/,
  /alguna\s+excepci/,
  /posible\s+una\s+excepci/,
  /equipo\s+(ya|lo)\b/,
];

// M14.4 — check ALL unanswered messages, not just the latest
let unansweredMsgs = [];
try { unansweredMsgs = $node["Build Conversation Context"].json.unanswered_recent_user_messages || []; } catch(e) {}

// Fall back to latestMsg if unanswered list is empty
const msgsToCheck = unansweredMsgs.length > 0 ? unansweredMsgs : (latestMsg ? [latestMsg] : []);

const isInformational = msgsToCheck.some(
  msg => INFORMATIONAL_PATTERNS.some(p => p.test(msg.toLowerCase().trim()))
);

return [{ json: { ...$json, is_informational_followup: isInformational, unanswered_faq_messages: msgsToCheck } }];

// M17 - Parse WhatsApp Flow booking submission
const body = $json.body || {};
const flowData = body.flow_response || {};
const threadId = body.thread_id;
