// Restore reply text lost when 'Needs Human flag' ON overwrote data with lead object
const zoneReply = $node["Zone Not Found Reply"].json;
const replyText = (zoneReply?.final_reply_text || zoneReply?.text || "").trim();
return [{ json: { final_reply_text: replyText, text: replyText } }];

// M17.4 Fix 5 — backend offline visibility
const item = $input.first()?.json ?? {};
const errMsg = item.error?.message || item.message || JSON.stringify(item);
const isConnRefused = /ECONNREFUSED|refused|offline/i.test(errMsg);

console.error('[M17.4] BACKEND_UNREACHABLE in Sync Lead State:', errMsg);

return [{
  json: {
    backend_offline: true,
    error_class: isConnRefused ? 'ECONNREFUSED' : 'BACKEND_ERROR',
    error_message: errMsg,
    action: 'execution_aborted_backend_unreachable',
    note: 'Candidate/state writes were NOT saved. Thread re-processes when backend recovers.'
  }
}];

// Normalize Revisions — collapse N revision items into exactly 1 item.
// Prevents paired-item ExpressionError when a lead has 2+ revisions.
const allItems = $input.all();
const revisions = allItems
  .map(item => item.json)
  .filter(r => r && typeof r.id !== 'undefined');

// Sort newest-first by id (API already returns newest-first, but be explicit).
revisions.sort((a, b) => (b.id || 0) - (a.id || 0));

return [{
  json: {
    revisions: revisions,
    latest_revision: revisions.length > 0 ? revisions[0] : null,
    revision_count: revisions.length
  }
}];

const results = [];

for (const item of $input.all()) {
  const body = (item.json && item.json.body) ? item.json.body : {};

  const isConversational = (
    body.event === "inbound_message" ||
    body.message_type === "audio" ||
    body.message_type === "image"
  );

  const rawThread = body.thread_id;
  const hasThreadId = (
    rawThread !== null &&
    rawThread !== undefined &&
    String(rawThread).trim() !== ""
  );

  const guardPassed = isConversational && hasThreadId;

  results.push({
    json: {
      ...item.json,
      guardPassed: guardPassed
    }
  });
}

return results;
